Rewrite the following GNU C++ code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
#include <algorithm>  
#include <iostream>  
#include <sstream>  
#include <string>  
#include <cstring>
#include <vector>  
#include <queue>  
#include <set>  
#include <map>  
#include <cstdio>  
#include <cstdlib>  
#include <cctype>  
#include <cmath>  
#include <list>  
#include <cassert>
#include <ctime>
#include <climits>
using namespace std;  

#define PB push_back  
#define MP make_pair  
#define SZ(v) ((int)(v).size())  
#define FOR(i,a,b) for(int i=(a);i<(b);++i)  
#define REP(i,n) FOR(i,0,n)  
#define FORE(i,a,b) for(int i=(a);i<=(b);++i)  
#define REPE(i,n) FORE(i,0,n)  
#define FORSZ(i,a,v) FOR(i,a,SZ(v))  
#define REPSZ(i,v) REP(i,SZ(v))  
typedef long long ll;
int gcd(int a,int b) { return b==0?a:gcd(b,a%b); }

const int MOD=1000000007;
const ll LIM=LLONG_MAX-(ll)MOD*MOD;
typedef int Mat[32][32];
ll n; int base;

void mmult(const Mat &A,const Mat &B,Mat &C) {
	REP(i,base+1) REP(j,base+1) {
		ll cur=0;
		REP(k,base+1) { if(cur>LIM) cur%=MOD; cur+=(ll)A[i][k]*B[k][j]; }
		C[i][j]=cur%MOD;
	}
}
void mcopy(const Mat &A,Mat &B) {
	REP(i,base+1) REP(j,base+1) B[i][j]=A[i][j];
}
void printmat(const Mat &A) {
	REP(i,base+1) { REP(j,base+1) printf("%2d ",A[i][j]); puts(""); }
}

Mat mat[60][32]; // mat[i][j] = matrix for sequence of base^i integers, starting with j

Mat have,tmp;

void run() {
	cin>>n>>base;
	REP(i,base) REP(j,base+1) REP(k,base+1) mat[0][i][j][k]=i==j||j==k?1:0;
	int ci=0,cj=0; ll step=1;
	while(step<=n/base) ++ci,step*=base;

	FORE(i,1,ci) REP(j,base) {
		REP(k,base+1) REP(l,base+1) mat[i][j][k][l]=k==l?1:0;
		REP(k,base) { mmult(mat[i][j],mat[i-1][(j+k)%base],tmp); mcopy(tmp,mat[i][j]); }
	}

	REP(k,base+1) REP(l,base+1) have[k][l]=k==l?1:0;
	for(;ci>=0;--ci,step/=base) {
		int times=(n/step)%base;
		REP(x,times) { 
			mmult(have,mat[ci][cj],tmp); mcopy(tmp,have); 
			//printf("after %d times %d^%d (starting with %d)\n",x+1,base,ci,cj); printmat(have); printf("\tmult with\n"); printmat(mat[ci][cj]);
			if(++cj>=base) cj-=base;
		}
	}
	//printf("have\n"); printmat(have);
	int ret=0; REP(k,base+1) { ret+=have[k][base]; if(ret>=MOD) ret-=MOD; }
	printf("%d\n",ret);
}

int main() {
	run();
	return 0;
}
